local Core = script.Parent.Parent.Parent.Parent
local ServiceCollection = require(script.Parent.Parent.Parent.Parent.Core.DependencyInjection.ServiceCollection)
local HostBuilderContext = require(script.Parent.Parent.Parent.Parent.Core.Hosting.HostBuilderContext)
local ServiceDescriptor = require(script.Parent.Parent.Parent.Parent.Core.DependencyInjection.ServiceDescriptor)
local InstancePathManager = require(script.Parent.Parent.Parent.Parent.Core.InstancePathManager)

local function getServiceDescriptors(
	item: Instance,
	lifeTimes: { [string]: "Singleton" | "Transient" | "Scope" },
	hostBuilderContext: IHostBuilderContext
): ServiceDescriptor?
	local descriptor = nil
	local path = InstancePathManager.GetPathAndCache(item)
	local luaConfigs = hostBuilderContext.HostingEnvironment.LuaTypeProvider.Types

	local luaType = luaConfigs[path]
	if not luaType then
		return nil
	end

	if luaType.__OnlyDefine then
		return nil
	end

	-- if k contains CardUISystem
	if string.find(luaType.FullName, "CardUISystem") then
		print(luaType.FullName)
	end

	local typeLifeTime = luaType.__LifeTime

	local lifetime = lifeTimes[path] or typeLifeTime or "Singleton"

	-- 检查上下文是否匹配
	if not hostBuilderContext.HostingEnvironment:MatchContext(luaType.__Context) then
		return nil
	end

	local serviceName = luaType.Name or luaType.FullName

	descriptor = ServiceDescriptor.newWithType(serviceName, path, lifetime)

	return descriptor
end

return getServiceDescriptors
